<script id="rampart-strategy">
function createStrategy() {
  const artillery = [0, 2, 3, 4, 6, 8, 11, 12, 9, 10, 13, 7, 5, 1, 14, 15];
  const order = [];
  function add(slot, type, level) { order.push({slot, type, level}); }
  add(0,'"'cannon',1);
  add(0,'cannon',2);
  add(2,'cannon',1);
  add(1,'flak',1);
  add(2,'cannon',2);
  add(0,'cannon',3);
  add(3,'cannon',1);
  add(1,'flak',2);
  add(2,'cannon',3);
  add(4,'cannon',1);
  add(4,'cannon',2);
  add(3,'cannon',2);
  add(10,'flak',1);
  add(10,'flak',2);
  add(1,'flak',3);
  for (const s of artillery) {
    const type = [1,5,10,15].includes(s) ? 'flak' : 'cannon';
    for(let level=1;level<=3;level++)add(s,type,level);
  }
  return {
    plan(state) {
      let gold = state.gold;
      const tiers = state.slots.map(s=>s.turret ? s.turret.tier : 0);
      const actions = [];
      for(const {slot,type,level} of order) {
        if(tiers[slot]>=level)continue;
        const cost=(type==='cannon'?90:80)*(level===3?2:1);
        if(gold<cost)break;
        actions.push(level===1?{op:'build',slot,type}:{op:'upgrade',slot});
        gold-=cost; tiers[slot]=level;
      }
      return actions;
    },
    target(t, cs) {
      const splash=t.type==='cannon'?90:70;
      const damage=(t.type==='cannon'?[60,96,153]:[40,64,102])[t.tier-1];
      let best=-1, result=cs[0].id;
      for(const c of cs) {
        let value=0;
        for(const e of cs) {
          const dx=c.x-e.x, dy=c.y-e.y;
          if(dx*dx+dy*dy>splash*splash)continue;
          const hit=Math.min(damage-e.armor,e.hp);
          value+=(0.3+0.7*hit/damage+(e.hp<=damage-e.armor?0.8:0))*(1+1.3/(1+e.remaining/800))*(e.type==='mender'?1.6:1);
        }
        if(value>best){best=value;result=c.id;}
      }
      return result;
    }
  };
}
</script>
<script id=\"rampart-sim\">
function rampartSimulate(createStrategy, seed, maxTicks) {
  const observer=arguments[3];
  const log=[], strategy=createStrategy(), enemies=[], queue=[];
  const coords=[[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const routes=[[[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],[[0,6],[21,6],[21,11],[23,11]]];
  const names=['grunt','runner','wisp','brute','splitter','mender','splitling'];
  const hpBase=[60,40,50,150,90,70,0], speeds=[10,20,12,6,8,8,12], bounties=[4,4,6,9,6,7,1], leaks=[1,1,2,3,2,2,1];
  const first=[1,2,3,4,6,8], weights=[10,4,3,3,2,1];
  const kinds=['bolt','cannon','frost','lance','flak'], prices=[50,90,70,120,80], power=[26,60,10,180,40], periods=[8,24,12,36,10], ranges=[300,260,240,360,320], splash=[0,90,0,0,70];
  const slots=coords.map(([x,y],slot)=>({slot,x:x*100+50,y:y*100+50,turret:null}));
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a "'^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0; }; }
  const draw=mulberry32(seed);
  function waveTypes(w) {
    let sum=0;
    for(let i=0;i<6;i++)if(first[i]<=w)sum+=weights[i];
    return Array.from({length:4+Math.floor(3*w/5)},()=>{
      let r=draw()%sum, i=0;
      while(r>=weights[i])r-=weights[i++];
      return i;
    });
  }
  let tick=0,wave=0,gold=250,baseHp=10,id=0,fallTick=-1;
  let next=waveTypes(1), mult=1000;
  const emit=(code,data)=>{if(observer)observer.event(tick,code,data);};
  function locate(e) {
    let p=e.progress;
    const path=routes[e.air];
    for(let i=1;i<path.length;i++) {
      const [x,y]=path[i-1], dx=path[i][0]-x, dy=path[i][1]-y, len=100*(Math.abs(dx)+Math.abs(dy));
      if(p<=len || i===path.length-1){
        e.x=100*x+50+Math.sign(dx)*p;e.y=100*y+50+Math.sign(dy)*p;
        e.dir=dx>0?1:dx<0?3:dy>0?0:2; break;
      }
      p-=len;
    }
    e.remaining=(e.air?2600:4600)-e.progress;
  }
  function spawn(kind,w,hp,p) {
    const e={id:++id,kind,type:names[kind],wave:w,progress:p,hp,maxHp:hp,speed:speeds[kind],armor:kind===3?6+w:kind===0?Math.floor(w/4):0,air:kind===2?1:0,age:0,slowed:0};
    locate(e);enemies.push(e);
  }
  function view(e) {
    const {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining}=e;
    return {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining};
  }
  function slotView(s) {
    const t=s.turret;
    return {slot:s.slot,x:s.x,y:s.y,turret:t?{type:t.type,tier:t.tier,spent:t.spent}:null};
  }
  const dist=(a,b)=>(a.x-b.x)*(a.x-b.x)+(a.y-b.y)*(a.y-b.y);
  const domain=(k,e)=>e.air ? k!==1 && k!==3 : k!==4;
  function planWave() {
    wave++; if(wave>1)mult=Math.floor(mult*108/100);
    gold+=Math.min(50,Math.floor(gold*5/100))+10+2*wave;
    const current=next; next=waveTypes(wave+1);
    const preview=next.map(i=>names[i]);
    emit('"'wave',{wave,preview});
    const actions=strategy.plan({tick,wave,gold,baseHp,slots:slots.map(slotView),enemies:enemies.map(view),nextWave:preview.slice()});
    for(const a of (Array.isArray(actions)?actions.slice(0,32):[])) {
      if("'!a || !Number.isInteger(a.slot) || !slots[a.slot])continue;
      const s=slots[a.slot], t=s.turret;
      if(a.op==='"'build' && "'!t) {
        const k=kinds.indexOf(a.type);
        if(k<0 || prices[k]>gold)continue;
        gold-=prices[k];
        s.turret={kind:k,type:kinds[k],tier:1,spent:prices[k],damage:power[k],range:ranges[k],cooldown:0,aim:0};
        log.push([tick,'"'B',s.slot,k]);emit('build',{slot:s.slot});
      } else if(a.op==='upgrade' && t && t.tier<3) {
        const cost=prices[t.kind]*t.tier;
        if(gold<cost)continue;
        gold-=cost;t.spent+=cost;t.tier++;t.damage=Math.floor(t.damage*16/10);t.range+=30;
        log.push([tick,'U',s.slot,t.tier]);emit('upgrade',{slot:s.slot});
      } else if(a.op==='sell' && t) {
        gold+=Math.floor(t.spent*70/100);s.turret=null;
        log.push([tick,'S',s.slot,0]);emit('sell',{slot:s.slot});
      }
    }
    current.forEach((kind,i)=>queue.push({due:tick+4*i,w:wave,i,kind,hp:Math.floor(hpBase[kind]*mult/1000)}));
    queue.sort((a,b)=>a.due-b.due||a.w-b.w||a.i-b.i);
  }
  for(;tick<maxTicks;tick++) {
    if(tick>=20 && (tick-20)%40===0)planWave();
    while(queue.length && queue[0].due===tick){const q=queue.shift();spawn(q.kind,q.w,q.hp,0);}
    for(let i=0;i<enemies.length;i++) {
      const e=enemies[i];
      e.progress+=e.slowed?Math.floor(e.speed*60/100):e.speed;
      locate(e);
      if(e.remaining<=0) {
        baseHp-=leaks[e.kind];log.push([tick,'L',e.id,baseHp]);
        emit('leak',{id:e.id,hp:baseHp,x:e.x,y:e.y});
        enemies.splice(i--,1);
        if(baseHp<=0) {fallTick=tick;log.push([tick,'F',wave,0]);emit('fall',{});break;}
      }
    }
    if(fallTick<0) {
      for(const e of enemies) {
        e.age++;
        if(e.kind===5 && e.age%20===0) {
          for(const v of enemies)if(dist(v,e)<=22500)v.hp=Math.min(v.maxHp,v.hp+Math.floor(v.maxHp*8/100));
          emit('heal',{x:e.x,y:e.y});
        }
      }
      for(const s of slots) {
        const t=s.turret; if("'!t)continue;
        if(t.cooldown>0 && --t.cooldown>0)continue;
        const range2=t.range*t.range,k=t.kind;
        const cs=enemies.filter(e=>domain(k,e)&&dist(s,e)<=range2);
        if(!cs.length)continue;
        let target;
        if(strategy.target) {
          const picked=strategy.target({slot:s.slot,type:t.type,tier:t.tier,x:s.x,y:s.y,range:t.range},cs.map(view));
          target=cs.find(e=>e.id===picked);
        }
        if(!target)target=cs.reduce((a,b)=>b.remaining<a.remaining?b:a);
        const victims=splash[k]?enemies.filter(e=>domain(k,e)&&dist(target,e)<=splash[k]*splash[k]):[target];
        for(const e of victims){e.hp-=Math.max(1,t.damage-(k===3?0:e.armor));if(k===2)e.slowed=30;}
        t.cooldown=periods[k];
        if(observer){
          t.aim=Math.atan2(target.x-s.x,target.y-s.y);
          emit('"'shot',{slot:s.slot,kind:k,x:target.x,y:target.y,air:target.air,aim:t.aim});
        }
        for(let i=0;i<enemies.length;i++) {
          const e=enemies[i];if(e.hp>0)continue;
          enemies.splice(i--,1);gold+=bounties[e.kind];
          log.push([tick,'K',e.id,s.slot]);
          emit('kill',{id:e.id,kind:e.kind,x:e.x,y:e.y,air:e.air});
          if(e.kind===4)for(let j=0;j<3;j++)spawn(6,e.wave,Math.max(1,Math.floor(e.maxHp/4)),e.progress);
        }
      }
      for(const e of enemies)if(e.slowed>0)e.slowed--;
    }
    if(observer)observer.frame(tick,wave,gold,baseHp,slots,enemies);
    if(fallTick>=0)break;
  }
  let h=0x811c9dc5;const str=JSON.stringify(log);
  for(let i=0;i<str.length;i++)h=Math.imul(h"'^str.charCodeAt(i),0x01000193);
  return {score:Math.round(((fallTick<0?maxTicks:fallTick)-20)*100/40)/100,fallTick,log,hash:(h>>>0).toString(16).padStart(8,'"'0')};
}
</script>
