function createStrategy() {
  const artillery = [0, 2, 3, 4, 6, 8, 11, 12, 9, 10, 13, 7, 5, 1, 14, 15];
  const order = [];
  function add(slot, type, level) { order.push({slot, type, level}); }
  add(0,'"'cannon',1);
  add(0,'cannon',2);
  add(2,'cannon',1);
  add(1,'flak',1);
  add(2,'cannon',2);
  add(0,'cannon',3);
  add(3,'cannon',1);
  add(1,'flak',2);
  add(2,'cannon',3);
  add(4,'cannon',1);
  add(4,'cannon',2);
  add(3,'cannon',2);
  add(10,'flak',1);
  add(10,'flak',2);
  add(1,'flak',3);
  for (const s of artillery) {
    const type = [1,5,10,15].includes(s) ? 'flak' : 'cannon';
    for(let level=1;level<=3;level++)add(s,type,level);
  }
  return {
    plan(state) {
      let gold = state.gold;
      const tiers = state.slots.map(s=>s.turret ? s.turret.tier : 0);
      const actions = [];
      for(const {slot,type,level} of order) {
        if(tiers[slot]>=level)continue;
        const cost=(type==='cannon'?90:80)*(level===3?2:1);
        if(gold<cost)break;
        actions.push(level===1?{op:'build',slot,type}:{op:'upgrade',slot});
        gold-=cost; tiers[slot]=level;
      }
      return actions;
    },
    target(t, cs) {
      const splash=t.type==='cannon'?90:70;
      const damage=(t.type==='cannon'?[60,96,153]:[40,64,102])[t.tier-1];
      let best=-1, result=cs[0].id;
      for(const c of cs) {
        let value=0;
        for(const e of cs) {
          const dx=c.x-e.x, dy=c.y-e.y;
          if(dx*dx+dy*dy>splash*splash)continue;
          const hit=Math.min(damage-e.armor,e.hp);
          value+=(0.3+0.7*hit/damage+(e.hp<=damage-e.armor?0.8:0))*(1+1.3/(1+e.remaining/800))*(e.type==='mender'?1.6:1);
        }
        if(value>best){best=value;result=c.id;}
      }
      return result;
    }
  };
}
